const b = $json.body || $json;
const text = String(b.text || b.textLower || '').toLowerCase();
const from = String(b.from || '').trim();
const negocio = String(b.negocio || '').trim();
if (!text) return [{ json: { ok: true, intent: 'ignore', from, negocio, reply: '' } }];
const handoffKeys = ['humano', 'persona', 'asesor', 'llamar', 'operador'];
const citaKeys = ['cita', 'turno', 'agendar', 'reserva', 'horario disponible'];
const faqKeys = ['horario', 'precio', 'direccion', 'dirección', 'servicios', 'donde', 'cuánto', 'cuanto'];
let intent = 'faq';
if (handoffKeys.some(k => text.includes(k))) intent = 'handoff';
else if (citaKeys.some(k => text.includes(k))) intent = 'cita';
else if (faqKeys.some(k => text.includes(k))) intent = 'faq';
else intent = 'handoff';
return [{ json: {
  ok: true,
  sistema: '09-wasap-task-faq-citas',
  etapa: 'intent',
  from, negocio, text, intent,
  siguiente: intent === 'faq' ? 'responder_faq' : intent === 'cita' ? 'agendar_cita' : 'handoff_humano',
  at: new Date().toISOString()
}}];
